#!/usr/bin/env python3
"""Add a new native endpoint-bridge observation without rewriting prior cohorts."""
import shutil
from retained_prefix_workflow import D,read,write,sha
p=D/'paper';result=read(D/'A0_endpoint_bridge_checkpoint_01.json');tiny=read(D/'analysis_fork_tiny_regression_02/completion.json');assert result['passed'] and tiny['passed']
tex=p/'data/endpoint_bridge_and_fork_v14.tex';assert not tex.exists()
tex.write_text(r'''
\section{A native endpoint-vector bridge and analysis-state reuse}
A later strong-A0 trajectory supplies a concrete example of a CPD-flat step enabling subsequent timing improvement. The automated endpoint actor first accepts an owner-only transaction at unchanged CPD13.607436066820355 ns and eight fewer wire units. On its own refreshed current state, it rejects the primary and all-positive combined proposals because of endpoint-vector regressions, then accepts target-only repair at CPD13.599797732410934 ns, wire2070797/SB98/CB5067. This second step improves nine setup components without a regression; the complete two-step state improves eleven relative to the pristine start, reduces thirty-six wire units and preserves SB/CB. Full native legality, physical-resource audits, current STA and fixed endpoint/domain comparisons are complete for these accepted states; the overall actor remains running.

The four-target native request is byte-identical to the request that leaves CPD unchanged on pristine A0 at wire2070813. Thus the subsequent 7.638334409 ps CPD gain is not explained by changed target IDs, ordering or criticality fields in that request. It supports an interaction with the legally released owner state and native scheduling. Strict CPD rejects the first flat step; this is evidence for retaining a distinct endpoint-vector trajectory, not evidence that its final result will beat the independently running strict trajectory. All moves use the existing native weighted kernel. The latest accepted state's complete observation takes205.793 s (native analysis102.795 s, independent physical audit65.488 s and other preparation/vector work); this does not include initial routing and historical proposal creation and is not a cold algorithm time.

The legal archive now records123 observations, including the two rejected-but-legal proposals and the accepted state. Its joint quality projection includes strong baselines and has seven distinct BNN frontier groups. Root-relative budget and opportunity differences remain explicit. Some older U states retain SB/CB tradeoffs; seven SPMV, five eltwise and two BNN nonbaseline observations are conservatively quality-dominated by a matched-input strong baseline. These are observation counts, not independent configurations. Unknown comparable complete time prevents full five-dimensional elimination; endpoint-vector differences are also retained outside the four quality axes.

For the measured loading bottleneck, a separate default-off serial Linux observer forks workers after loading packing, placement and RRG but before reading a route or applying pin-equivalence synchronization. Each child runs the existing route LOAD, FULL check, synchronization, physical-delay calculation and native STA in a private copy-on-write state. A tiny equivalent-input fixture changes the actual IPIN from236 to208; complete endpoint/clock-domain/constraint and full-precision timing-graph outputs exactly match fresh standalone processes of the same binary. The five-worker sequence includes a malformed route whose native loader segfault also occurs standalone; subsequent valid workers are identical. This demonstrates process isolation, not graceful in-process rollback. Duplicate output directories are rejected before work. An initial compile-field error and a case-sensitive timer-label test failure remain recorded; the latter recovery reuses all three completed native parent processes and adds only the two missing rejection/failure controls. Zero new routing flows are used. Large-BNN equality is independently registered and running; no cold full-algorithm or formal speedup claim follows from the tiny test.
''')
main=p/'main.tex';s=main.read_text();needle=r'\input{data/endpoint_bridge_and_fork_v14.tex}';assert needle not in s;s=s.replace(r'\section{Conclusion}',needle+'\n\n'+r'\section{Conclusion}');main.write_text(s)
with (p/'claims_evidence.md').open('a') as f:
 f.write('\n| C131 | 强A0端点平台步骤后，同字节目标请求取得后续CPD收益 | [2步与匹配初态对照](../A0_endpoint_bridge_checkpoint_01.json)、[档案23](../multiobjective_archive_23/completion.json)、[联合质量投影](../multiobjective_tradeoff_summary_06.json) | owner-only先平CPD，再target-only达到13.599797732ns；wire较原A0少36，SB/CB不变，11setup改善0退化。原初态同4目标请求CPD平；旧严格策略拒绝第一步。当前轨迹未终态，不声称胜过独立strict分支或冷完整加速 |\n')
 f.write('| C132 | 独立预route载入fork保留新鲜pin同步和完整native分析 | [stage02构建](../analysis_fork_stage_02/binding.json)、[小图恢复验证](../analysis_fork_tiny_regression_02/completion.json)、[首次测试失败](../analysis_fork_validation_queue_01/completion.json)、[构建修复](../analysis_fork_build_recovery_01.json) | 实际IPIN236→208的完整精度STA/constraints/graph同新二进制独立进程；5worker含已独立复现的无效route SIG11，后继合法分析一致。复用3旧parent进程、只补2缺失检查；0新routeflow。大图等价仍进行，无完整算法加速结论 |\n')
with (p/'mechanisms_and_ablation.md').open('a') as f:f.write('\nC131–C132：强A0的端点平台接受为随后同请求CPD改善提供真实反例；原native核不变。载入复用用预route私有fork而非沿用已同步pin映射；小图通过，实际大图仍在验证。原始失败与完整时间未知均保留。\n')
status=p/'DEVELOPMENT_STATUS.md';s=status.read_text();status.write_text('# 最新观察补充 C131–C132\n\n强A0 endpoint已接受两步，达到13.599797732410934ns/wire2070797/SB98/CB5067；较封存起点CPD好7.638334ps、wire少36，11setup改善0退化。首步CPD持平、严格策略拒绝；后续4目标请求同初态字节完全一致但初态无CPD收益。当前actor仍继续，不是终态性能结论。档案23=123观察。\n\n独立analysis_fork_stage_02构建及小图恢复验证通过，实际pin映射更换仍与同二进制独立完整分析完全相同。大BNN工程等价运行中；active quality cohort版本不变。所有新内容仅本地、未推送；冷完整算法时间未知。\n\n'+s)
ledger=p/'data/evidence_v14_ledger.json';history=p/'data/ledger_history_20261113/before_endpoint_bridge_01.json';assert not history.exists();shutil.copy2(ledger,history);a=read(ledger)
for f in [tex,D/'A0_endpoint_bridge_checkpoint_01.json',D/'multiobjective_archive_23/completion.json',D/'multiobjective_archive_23/points.csv',D/'multiobjective_tradeoff_summary_06.json',D/'analysis_fork_stage_02/binding.json',D/'analysis_fork_tiny_regression_02/completion.json',D/'analysis_fork_validation_queue_01/completion.json',D/'analysis_fork_build_recovery_01.json']:a['sources_sha256'][str(f.relative_to(D))]=sha(f)
write(ledger,a)
print(dict(new_claims=['C131','C132'],sources=len(a['sources_sha256'])))
